    const before = {sessionId: 'session-1', updatedAt: '2026-10-27T10:00:00.000Z'};

    expect([
      validateMessage({type: 'list_sessions'}),
      validateMessage({type: 'list_sessions', limit: 5, before, userId: 'someone-else'}),
